using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Game.Character;
using Game.Stage;

namespace Game.Tests
{
    /// <summary>
    /// プレイヤーとステージの連携を検証するクラス。
    ///
    /// 初期化、移動、宝石取得、ポーズ、速度変更、
    /// ステージクリア、再生成を検証する。
    /// </summary>
    public class MazePlayerControllerTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("参照設定")]

        /// <summary>ステージ管理クラス。</summary>
        [SerializeField]
        private MazeStageManager stageManager;

        /// <summary>プレイヤー接続クラス。</summary>
        [SerializeField]
        private MazePlayerStageBinder playerBinder;

        [Header("テスト設定")]

        /// <summary>開始時に自動テストを実行するか。</summary>
        [SerializeField]
        [Tooltip("開始時に結合テストを実行する")]
        private bool runTestsOnStart = true;

        /// <summary>テスト後に新しいステージを開始するか。</summary>
        [SerializeField]
        [Tooltip("テスト成功後に手動プレイへ移行する")]
        private bool startManualPlayAfterTests = true;

        [Header("テスト結果")]

        /// <summary>成功したテスト項目数。</summary>
        [SerializeField]
        private int passedCount;

        /// <summary>失敗したテスト項目数。</summary>
        [SerializeField]
        private int failedCount;

        #endregion

        #region Runtime Fields

        /// <summary>現在イベントを監視しているプレイヤー。</summary>
        private MazePlayerController observedPlayer;

        /// <summary>宝石取得イベントの発生回数。</summary>
        private int gemEventCount;

        /// <summary>セル到達イベントの発生回数。</summary>
        private int cellEventCount;

        /// <summary>クリアイベントの発生回数。</summary>
        private int clearEventCount;

        /// <summary>自動テストを実行中か。</summary>
        private bool isTesting;

        /// <summary>位置・時間比較用の許容誤差。</summary>
        private const float Tolerance = 0.001f;

        #endregion

        #region Unity Methods

        /// <summary>シーン開始時の処理。</summary>
        private IEnumerator Start()
        {
            if (!ValidateReferences())
            {
                yield break;
            }

            stageManager.StageGenerated += OnStageGenerated;
            stageManager.StageCleared += OnStageCleared;

            // 他コンポーネントのStart完了を待つ。
            yield return null;

            if (runTestsOnStart)
            {
                RunAllTests();
            }
            else
            {
                ObservePlayer(playerBinder.CurrentPlayer);
            }
        }

        /// <summary>コンポーネント破棄時の処理。</summary>
        private void OnDestroy()
        {
            if (stageManager != null)
            {
                stageManager.StageGenerated -=
                    OnStageGenerated;

                stageManager.StageCleared -=
                    OnStageCleared;
            }

            ObservePlayer(null);
        }

        #endregion

        #region Test Control Methods

        /// <summary>すべての結合テストを実行する。</summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        public void RunAllTests()
        {
            if (!Application.isPlaying ||
                isTesting ||
                !ValidateReferences())
            {
                return;
            }

            StartCoroutine(RunTestsCoroutine());
        }

        /// <summary>
        /// フレームをまたいで結合テストを実行する。
        /// </summary>
        /// <returns>テスト実行用IEnumerator</returns>
        private IEnumerator RunTestsCoroutine()
        {
            isTesting = true;

            passedCount = 0;
            failedCount = 0;

            Debug.Log(
                "【MazePlayerController 結合テスト開始】",
                this);

            // テスト専用設定でステージを生成する。
            MazeStageGenerationSettings settings =
                CreateTestSettings();

            bool generated =
                stageManager.GenerateStage(settings);

            Check(generated, "テストステージの生成");

            yield return null;

            MazePlayerController player =
                playerBinder.CurrentPlayer;

            Check(
                player != null,
                "プレイヤーの生成");

            Check(
                playerBinder.HasPlayer,
                "プレイヤーとの接続");

            if (!generated ||
                player == null ||
                !player.IsInitialized)
            {
                FinishTests();
                yield break;
            }

            ObservePlayer(player);

            TestInitialization(player);

            // AutoStartStageが無効な場合にも対応する。
            if (stageManager.State == MazeStageState.Ready)
            {
                stageManager.StartStage();
            }

            Check(
                stageManager.IsPlaying,
                "ステージの開始");

            Check(
                player.CanAct,
                "プレイヤーの行動許可");

            Check(
                !player.Movement.IsPaused,
                "移動処理の再開");

            TestSpeed(player);

            TestInvalidDirection(player);

            // 宝石が配置された隣接セルを検索する。
            bool found = TryFindAdjacentGem(
                player.CurrentCell,
                out Vector2Int direction);

            Check(found, "隣接する宝石セルの取得");

            if (!found)
            {
                FinishTests();
                yield break;
            }

            TestMovementAndCollection(player, direction);

            TestPause(player);

            // ポーズ中に経過時間が増加しないことを確認する。
            float pausedTime = stageManager.ElapsedTime;

            yield return null;
            yield return null;

            Check(
                Mathf.Abs(
                    stageManager.ElapsedTime - pausedTime)
                    <= Tolerance,
                "ポーズ中の経過時間停止");

            TestResume(player);

            TestClear(player);

            // ステージ再生成によるプレイヤーの交換を検証する。
            TestRegeneration(player, settings);

            FinishTests();
        }

        /// <summary>
        /// 結合テスト専用のステージ設定を生成する。
        /// </summary>
        /// <returns>テスト用ステージ生成設定</returns>
        private MazeStageGenerationSettings CreateTestSettings()
        {
            MazeStageGenerationSettings settings =
                new MazeStageGenerationSettings();

            settings.MazeSettings.Width = 15;
            settings.MazeSettings.Height = 11;
            settings.MazeSettings.UseFixedSeed = true;
            settings.MazeSettings.Seed = 12345;

            // 通行可能な隣接セルへ宝石が配置されるようにする。
            settings.EnemyCount = 0;
            settings.InitialItemCount = 0;
            settings.ItemSpawnCount = 0;
            settings.GemRate = 1f;
            settings.BreakableWallRate = 0f;

            return settings;
        }

        /// <summary>テスト結果を出力して終了する。</summary>
        private void FinishTests()
        {
            isTesting = false;

            string message =
                "【MazePlayerController テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべての結合テストに成功しました。",
                    this);

                if (startManualPlayAfterTests)
                {
                    StartManualPlay();
                }
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        #endregion

        #region Automated Test Methods

        /// <summary>
        /// プレイヤーの初期化状態を検証する。
        /// </summary>
        /// <param name="player">テスト対象のプレイヤー</param>
        private void TestInitialization(
            MazePlayerController player)
        {
            Check(
                player.IsInitialized,
                "プレイヤーの初期化");

            Check(
                player.Movement != null,
                "移動コンポーネントの取得");

            Check(
                player.Movement.IsInitialized,
                "移動コンポーネントの初期化");

            Check(
                !player.Movement.AutoUpdate,
                "移動更新の二重実行防止");

            Check(
                player.CurrentCell ==
                stageManager.StageResult.PlayerSpawnPosition,
                "プレイヤーの初期セル座標");

            Check(
                player.Movement.IsAtCellCenter,
                "セル中心への初期配置");

            Check(
                stageManager.IsWalkable(player.CurrentCell),
                "初期位置の通行可能判定");
        }

        /// <summary>
        /// 移動速度変更機能を検証する。
        /// </summary>
        /// <param name="player">テスト対象のプレイヤー</param>
        private void TestSpeed(
            MazePlayerController player)
        {
            float originalSpeed = player.BaseMoveSpeed;

            player.SetBaseMoveSpeed(4f);

            Check(
                Mathf.Approximately(
                    player.CurrentMoveSpeed, 4f),
                "基本移動速度の変更");

            player.SetSpeedMultiplier(1.5f);

            Check(
                Mathf.Approximately(
                    player.CurrentMoveSpeed, 6f),
                "速度倍率の適用");

            Check(
                Mathf.Approximately(
                    player.Movement.MoveSpeed, 6f),
                "移動コンポーネントへの速度反映");

            player.ResetSpeedMultiplier();

            Check(
                Mathf.Approximately(
                    player.SpeedMultiplier, 1f),
                "速度倍率の初期化");

            Check(
                Mathf.Approximately(
                    player.Movement.MoveSpeed, 4f),
                "通常速度への復帰");

            player.SetBaseMoveSpeed(originalSpeed);
        }

        /// <summary>
        /// 不正な移動方向が拒否されるか検証する。
        /// </summary>
        /// <param name="player">テスト対象のプレイヤー</param>
        private void TestInvalidDirection(
            MazePlayerController player)
        {
            Check(
                !player.RequestDirection(Vector2Int.zero),
                "ゼロ方向の拒否");

            Check(
                !player.RequestDirection(
                    new Vector2Int(1, 1)),
                "斜め方向の拒否");

            Check(
                !player.RequestDirection(
                    new Vector2Int(2, 0)),
                "不正な方向ベクトルの拒否");
        }

        /// <summary>
        /// 移動と宝石取得の連携を検証する。
        /// </summary>
        /// <param name="player">テスト対象のプレイヤー</param>
        /// <param name="direction">移動する方向</param>
        private void TestMovementAndCollection(
            MazePlayerController player,
            Vector2Int direction)
        {
            Vector2Int startCell = player.CurrentCell;
            Vector2Int targetCell = startCell + direction;

            int previousGemCount =
                stageManager.RemainingGemCount;

            gemEventCount = 0;
            cellEventCount = 0;

            float originalSpeed = player.BaseMoveSpeed;

            player.SetBaseMoveSpeed(4f);

            Check(
                player.RequestDirection(direction),
                "移動方向の予約");

            // 1セルの半分だけ移動させる。
            player.Movement.Tick(0.125f);

            Check(
                player.Movement.IsTraversing,
                "セル間の移動開始");

            Check(
                player.CurrentCell == startCell,
                "移動中の現在セル維持");

            Check(
                stageManager.RemainingGemCount ==
                previousGemCount,
                "セル到達前の宝石取得防止");

            // 残り半分を移動させる。
            player.Movement.Tick(0.125f);

            Check(
                player.CurrentCell == targetCell,
                "目的セルへの到達");

            Check(
                stageManager.RemainingGemCount ==
                previousGemCount - 1,
                "宝石の自動取得");

            Check(
                !stageManager.Map.GetCell(targetCell).HasGem,
                "取得済み宝石のセル情報更新");

            Check(
                gemEventCount == 1,
                "宝石取得イベント");

            Check(
                cellEventCount == 1,
                "セル到達イベント");

            player.Movement.StopImmediately();

            player.SetBaseMoveSpeed(originalSpeed);
        }

        /// <summary>
        /// ポーズ中のプレイヤー状態を検証する。
        /// </summary>
        /// <param name="player">テスト対象のプレイヤー</param>
        private void TestPause(
            MazePlayerController player)
        {
            Vector3 previousPosition =
                player.transform.position;

            Check(
                stageManager.PauseStage(),
                "ステージのポーズ");

            Check(
                !player.CanAct,
                "ポーズ中の行動禁止");

            Check(
                player.Movement.IsPaused,
                "移動処理の一時停止");

            Check(
                !player.RequestDirection(Vector2Int.up),
                "ポーズ中の移動要求拒否");

            // 外部からTickを実行しても移動しないことを確認する。
            player.Movement.Tick(1f);

            Check(
                Vector3.Distance(
                    previousPosition,
                    player.transform.position) <= Tolerance,
                "ポーズ中の位置維持");
        }

        /// <summary>
        /// ポーズ解除後の状態を検証する。
        /// </summary>
        /// <param name="player">テスト対象のプレイヤー</param>
        private void TestResume(
            MazePlayerController player)
        {
            Check(
                stageManager.ResumeStage(),
                "ステージの再開");

            Check(
                player.CanAct,
                "再開後の行動許可");

            Check(
                !player.Movement.IsPaused,
                "再開後の移動許可");
        }

        /// <summary>
        /// 全宝石取得後のクリア処理を検証する。
        /// </summary>
        /// <param name="player">テスト対象のプレイヤー</param>
        private void TestClear(
            MazePlayerController player)
        {
            clearEventCount = 0;

            // 列挙中にセルを書き換えないよう、
            // 残っている宝石の座標を先に取得する。
            List<Vector2Int> gemPositions =
                new List<Vector2Int>(
                    stageManager.Map.FindPositions(
                        cell => cell.HasGem));

            // 最後の宝石だけ残す。
            for (int i = 0;
                 i < gemPositions.Count - 1;
                 i++)
            {
                stageManager.TryCollectGem(gemPositions[i]);
            }

            Check(
                stageManager.RemainingGemCount == 1,
                "最後の宝石を残した状態");

            if (gemPositions.Count == 0)
            {
                return;
            }

            Vector2Int lastGem =
                gemPositions[gemPositions.Count - 1];

            // 最後の宝石を取得する。
            // ここではステージのクリア連携を直接検証する。
            stageManager.TryCollectGem(lastGem);

            Check(
                stageManager.RemainingGemCount == 0,
                "全宝石の取得");

            Check(
                stageManager.State == MazeStageState.Cleared,
                "ステージクリア判定");

            Check(
                !player.CanAct,
                "クリア後の行動禁止");

            Check(
                player.Movement.IsPaused,
                "クリア直後の移動停止");

            Check(
                clearEventCount == 1,
                "クリアイベントの発生");

            Check(
                !player.RequestDirection(Vector2Int.right),
                "クリア後の移動要求拒否");
        }

        /// <summary>
        /// ステージ再生成時のプレイヤー接続を検証する。
        /// </summary>
        /// <param name="oldPlayer">再生成前のプレイヤー</param>
        /// <param name="settings">ステージ生成設定</param>
        private void TestRegeneration(
            MazePlayerController oldPlayer,
            MazeStageGenerationSettings settings)
        {
            Check(
                stageManager.GenerateStage(settings),
                "ステージの再生成");

            MazePlayerController newPlayer =
                playerBinder.CurrentPlayer;

            Check(
                newPlayer != null,
                "新しいプレイヤーの生成");

            Check(
                newPlayer != null &&
                !ReferenceEquals(oldPlayer, newPlayer),
                "プレイヤーインスタンスの交換");

            Check(
                oldPlayer == null ||
                !oldPlayer.IsInitialized,
                "古いプレイヤーの接続解除");

            Check(
                newPlayer != null &&
                newPlayer.IsInitialized,
                "新しいプレイヤーの初期化");

            Check(
                stageManager.RemainingGemCount ==
                stageManager.InitialGemCount,
                "再生成後の宝石数初期化");
        }

        #endregion

        #region Manual Test Methods

        /// <summary>通常設定で手動プレイを開始する。</summary>
        [ContextMenu("手動テスト/新しいステージを開始")]
        public void StartManualPlay()
        {
            if (!Application.isPlaying ||
                isTesting ||
                !ValidateReferences())
            {
                return;
            }

            if (!stageManager.GenerateStage())
            {
                return;
            }

            ObservePlayer(playerBinder.CurrentPlayer);

            if (stageManager.State == MazeStageState.Ready)
            {
                stageManager.StartStage();
            }

            Debug.Log(
                "【手動プレイ開始】\n" +
                "WASD・矢印キー：移動\n" +
                "Space：アイテム使用要求\n" +
                "E：召喚要求\n" +
                "Esc：ポーズ・再開",
                this);
        }

        /// <summary>現在のステージ情報を出力する。</summary>
        [ContextMenu("手動テスト/現在の状態を表示")]
        public void PrintCurrentState()
        {
            if (!Application.isPlaying ||
                stageManager == null)
            {
                return;
            }

            MazePlayerController player =
                playerBinder.CurrentPlayer;

            Debug.Log(
                "【現在のプレイ状態】\n" +
                $"ステージ状態：{stageManager.State}\n" +
                $"残り宝石：{stageManager.RemainingGemCount}\n" +
                $"取得済み宝石：{stageManager.CollectedGemCount}\n" +
                $"経過時間：{stageManager.ElapsedTime:F2}秒\n" +
                $"現在セル：{player?.CurrentCell}\n" +
                $"移動方向：{player?.CurrentDirection}",
                this);
        }

        #endregion

        #region Event Methods

        /// <summary>
        /// ステージ生成完了時のイベント処理。
        /// </summary>
        /// <param name="result">生成されたステージ情報</param>
        private void OnStageGenerated(
            MazeStageGenerationResult result)
        {
            ObservePlayer(playerBinder.CurrentPlayer);
        }

        /// <summary>
        /// プレイヤーの監視対象を変更する。
        /// </summary>
        /// <param name="player">新しい監視対象</param>
        private void ObservePlayer(
            MazePlayerController player)
        {
            if (observedPlayer != null)
            {
                observedPlayer.CellEntered -= OnCellEntered;
                observedPlayer.GemCollected -= OnGemCollected;
                observedPlayer.ItemCollected -= OnItemCollected;

                observedPlayer.ItemUseRequested -=
                    OnItemUseRequested;

                observedPlayer.SummonRequested -=
                    OnSummonRequested;
            }

            observedPlayer = player;

            if (observedPlayer == null)
            {
                return;
            }

            observedPlayer.CellEntered += OnCellEntered;
            observedPlayer.GemCollected += OnGemCollected;
            observedPlayer.ItemCollected += OnItemCollected;

            observedPlayer.ItemUseRequested +=
                OnItemUseRequested;

            observedPlayer.SummonRequested +=
                OnSummonRequested;
        }

        /// <summary>セル到達イベントを記録する。</summary>
        /// <param name="position">到達したセル座標</param>
        private void OnCellEntered(Vector2Int position)
        {
            cellEventCount++;
        }

        /// <summary>宝石取得イベントを記録する。</summary>
        /// <param name="position">取得したセル座標</param>
        private void OnGemCollected(Vector2Int position)
        {
            gemEventCount++;

            Debug.Log(
                $"宝石取得：{position} / " +
                $"残り：{stageManager.RemainingGemCount}",
                this);
        }

        /// <summary>アイテム取得イベントを記録する。</summary>
        /// <param name="position">取得したセル座標</param>
        private void OnItemCollected(Vector2Int position)
        {
            Debug.Log($"アイテム取得：{position}", this);
        }

        /// <summary>アイテム使用要求を確認する。</summary>
        private void OnItemUseRequested()
        {
            Debug.Log("アイテム使用要求", this);
        }

        /// <summary>召喚要求を確認する。</summary>
        private void OnSummonRequested()
        {
            Debug.Log("召喚要求", this);
        }

        /// <summary>ステージクリアイベントを記録する。</summary>
        /// <param name="elapsedTime">クリアまでの経過時間</param>
        private void OnStageCleared(float elapsedTime)
        {
            clearEventCount++;

            Debug.Log(
                "【ステージクリア！！】\n" +
                $"クリアタイム：{elapsedTime:F2}秒",
                this);
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 現在位置に隣接する宝石セルを検索する。
        /// </summary>
        /// <param name="position">検索元のセル座標</param>
        /// <param name="direction">宝石セルへの方向</param>
        /// <returns>宝石セルが見つかった場合はtrue</returns>
        private bool TryFindAdjacentGem(
            Vector2Int position,
            out Vector2Int direction)
        {
            foreach (Vector2Int neighbor in
                stageManager.Map.GetNeighbors(position))
            {
                if (stageManager.IsWalkable(neighbor) &&
                    stageManager.Map.GetCell(neighbor).HasGem)
                {
                    direction = neighbor - position;

                    return true;
                }
            }

            direction = Vector2Int.zero;

            return false;
        }

        /// <summary>
        /// 必要な参照を検証する。
        /// </summary>
        /// <returns>参照が正常な場合はtrue</returns>
        private bool ValidateReferences()
        {
            if (stageManager == null ||
                playerBinder == null)
            {
                Debug.LogError(
                    "プレイヤーテストに必要な参照を" +
                    "設定してください。",
                    this);

                return false;
            }

            return true;
        }

        /// <summary>テスト結果を記録する。</summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log($"[成功] {testName}", this);
            }
            else
            {
                failedCount++;

                Debug.LogError($"[失敗] {testName}", this);
            }
        }

        #endregion
    }
}
